from harness import *
from flow_dashboard import check
from flow_customers import login, ok_dialog

def go(pg, h): pg.evaluate(f"location.hash='#/{h}'"); pg.wait_for_timeout(1800)

def prompt(pg, value):
    pg.wait_for_selector('#dlgInput', timeout=5000); pg.fill('#dlgInput', value); pg.click('#dlgOk'); pg.wait_for_timeout(1000)

