def importing(pg):
    ok = True
    go(pg, 'import')
    pg.click('#importFileBtn'); ok &= check('I-01 asks for a file first', pg.inner_text('#importHint') == 'Choose a file first.')
    with pg.expect_download() as dl: pg.click('#downloadTemplateBtn')
    ok &= check('I-01 template download', dl.value.suggested_filename == 'anupam360-import-template.xlsx', dl.value.suggested_filename)
    csv = 'Company,Plant,City,State,Potential,Contact Name,Phone\nacme bearings,P1,Chennai,Tamil Nadu,high,ravi kumar,9000000001\nAcme Bearings,,,,,sita devi,9000000002\nHindustan Gearbox Works,,Ambattur,,,Newbie One,9000000003\n'
    pg.set_input_files('#importFileInput', files=[{'name': 'x.csv', 'mimeType': 'text/csv', 'buffer': csv.encode()}])
    pg.click('#importFileBtn'); pg.wait_for_timeout(5000)
    t = pg.inner_text('#importResult')
    ok &= check('I-01 one new customer with two contacts, one customer updated', 'Imported 1 new customer(s), updated 1, added 3 new contact(s).' in t, t)
    go(pg, 'customers'); pg.fill('#searchInput', 'acme'); pg.wait_for_timeout(500)
    ok &= check('I-01 the imported customer is in the list (title-cased)', pg.locator('.card[data-cid]').count() == 1 and 'Acme Bearings' in pg.inner_text('.card[data-cid]'))
    return ok

def backup(pg):
    ok = True
    go(pg, 'backup')
    ok &= check('B-01 count chips and last-backup line', pg.locator('#backupSummary span').count() == 8 and 'No backup has been downloaded' in pg.inner_text('#backupSummary'), pg.inner_text('#backupSummary'))
    with pg.expect_download() as dl: pg.click('#backupBtn')
    path = dl.value.path(); ok &= check('B-01 backup downloads as a JSON file', dl.value.suggested_filename.endswith('.json') and open(path, 'rb').read(1) == b'{', dl.value.suggested_filename)
    pg.wait_for_timeout(2500)
    ok &= check('B-01 last backup line updates', 'Last backup downloaded:' in pg.inner_text('#backupSummary'))
    pg.click('#restoreBtn'); ok &= check('B-01 restore needs a file', pg.inner_text('#restoreHint') == 'Choose a backup file first.')
    pg.set_input_files('#restoreFileInput', path); pg.wait_for_timeout(1500)
    ok &= check('B-01 the file is described before restoring', 'This file has:' in pg.inner_text('#restoreHint') and 'customers' in pg.inner_text('#restoreHint'), pg.inner_text('#restoreHint'))
    pg.click('#restoreBtn'); pg.wait_for_timeout(500)
    ok &= check('B-01 restore asks for confirmation', 'This replaces the current data' in pg.inner_text('body')); ok_dialog(pg); pg.wait_for_timeout(4000)
    ok &= check('B-02 restore completes and a safety copy is named', 'Restore complete' in pg.inner_text('#restoreHint') and 'safety-copy' in pg.inner_text('#restoreHint'), pg.inner_text('#restoreHint'))
    go(pg, 'customers'); ok &= check('B-02 data is still there after the round trip', pg.locator('.card[data-cid]').count() >= 6)
    return ok

