def branches(pg):
    ok = True
    go(pg, 'branches')
    ok &= check('BR-01 app logo and sidebar logo panels', all(pg.locator(f'#{i}').count() == 1 for i in ('appLogoPreview', 'appLogoInput', 'appLogoResetBtn', 'sidebarLogoPreview', 'sidebarLogoInput', 'sidebarLogoResetBtn')))
    ok &= check('BR-01 two branches listed with four buttons each', pg.locator('#branchesList .manage-item').count() == 2 and pg.locator('#branchesList .manage-item').first.locator('button').count() == 4)
    import struct, zlib
    def png(w, h, rgb):
        raw = b''.join(b'\x00' + bytes(rgb) * w for _ in range(h))
        chunk = lambda t, d: struct.pack('>I', len(d)) + t + d + struct.pack('>I', zlib.crc32(t + d) & 0xffffffff)
        return b'\x89PNG\r\n\x1a\n' + chunk(b'IHDR', struct.pack('>IIBBBBB', w, h, 8, 2, 0, 0, 0)) + chunk(b'IDAT', zlib.compress(raw)) + chunk(b'IEND', b'')
    pg.set_input_files('#appLogoInput', files=[{'name': 'l.png', 'mimeType': 'image/png', 'buffer': png(60, 20, (200, 30, 30))}]); pg.wait_for_timeout(2000)
    ok &= check('BR-01 app logo upload: hint, preview and sidebar change', pg.inner_text('#appLogoHint') == 'Logo updated.' and '/media/' in pg.get_attribute('#appLogoPreview', 'src') and '/media/' in pg.get_attribute('#logoRowApp img', 'src') and '/media/' in pg.get_attribute('#logoRowMobile img', 'src'), pg.get_attribute('#logoRowApp img', 'src'))
    pg.set_input_files('#sidebarLogoInput', files=[{'name': 's.png', 'mimeType': 'image/png', 'buffer': png(40, 40, (30, 30, 200))}]); pg.wait_for_timeout(2000)
    ok &= check('BR-01 sidebar logo is separate from the app logo', pg.inner_text('#sidebarLogoHint') == 'Sidebar logo updated.' and 'sidebar_logo' in pg.get_attribute('#logoRowApp img', 'src') and 'app_logo' in pg.get_attribute('#logoRowMobile img', 'src'))
    pg.reload(); pg.wait_for_timeout(2500)
    ok &= check('BR-01 the logos persist across a reload', 'sidebar_logo' in pg.get_attribute('#logoRowApp img', 'src') and 'app_logo' in pg.get_attribute('#logoRowMobile img', 'src'))
    go(pg, 'branches')
    pg.click('#sidebarLogoResetBtn'); pg.wait_for_timeout(1200); pg.click('#appLogoResetBtn'); pg.wait_for_timeout(1200)
    ok &= check('BR-01 reset goes back to the built-in logos', 'logo-on-dark' in pg.get_attribute('#logoRowApp img', 'src') and 'logo-on-light' in pg.get_attribute('#logoRowMobile img', 'src') and pg.inner_text('#appLogoHint') == 'Back to the default logo.', pg.get_attribute('#logoRowApp img', 'src'))
    pg.fill('#newBranchInput', 'Test Branch'); pg.click('#addBranchBtn'); pg.wait_for_timeout(1200)
    ok &= check('BR-01 create a branch', pg.locator('#branchesList .manage-item').count() == 3 and 'Test Branch' in pg.inner_text('#branchesList'))
    row = lambda: pg.locator('.manage-item', has_text='Test Branch')
    row().locator('[data-act="rename"]').click(); prompt(pg, 'Test Branch 2')
    ok &= check('BR-01 rename', 'Test Branch 2' in pg.inner_text('#branchesList'))
    row().locator('[data-act="details"]').click(); pg.wait_for_timeout(500)
    ok &= check('BR-02 details dialog: title and all the letterhead fields', pg.inner_text('#branchDetailTitle') == 'Branch Details — Test Branch 2' and all(pg.locator(f'#{i}').count() == 1 for i in ('bd-companyname', 'bd-address', 'bd-phone', 'bd-mobile', 'bd-email', 'bd-website', 'bd-gst', 'bd-udyam', 'bd-docfmt', 'bd-wm-enabled', 'bd-wm-type', 'bd-wm-size', 'bd-wm-text', 'bd-accent', 'bd-bank-acno', 'bd-bank-ifsc', 'bd-bank-name', 'bd-bank-branch')))
    for i, v in (('bd-companyname', 'Acme Co'), ('bd-address', '1 Main St, Chennai'), ('bd-phone', '044 1'), ('bd-mobile', '90000 11111'), ('bd-email', 'a@b.co'), ('bd-website', 'acme.co'), ('bd-gst', '29ABCDE1234F1Z5'), ('bd-udyam', 'UDYAM-1'), ('bd-bank-acno', '123'), ('bd-bank-ifsc', 'HDFC0001'), ('bd-bank-name', 'HDFC'), ('bd-bank-branch', 'Anna Nagar')): pg.fill('#' + i, v)
    pg.select_option('#bd-docfmt', '2'); pg.check('#bd-wm-enabled'); pg.select_option('#bd-wm-type', 'text'); pg.fill('#bd-wm-text', 'COPY'); pg.select_option('#bd-wm-size', 'large'); pg.fill('#bd-accent', '#112233')
    pg.set_input_files('#bd-logo-input', files=[{'name': 'l.png', 'mimeType': 'image/png', 'buffer': png(30, 30, (10, 200, 10))}]); pg.wait_for_timeout(400)
    ok &= check('BR-02 a chosen logo is previewed before saving', pg.is_visible('#bd-logo-preview'))
    pg.click('#branchDetailSaveBtn'); pg.wait_for_timeout(2000)
    ok &= check('BR-02 saved: confirmation message', 'Branch details saved' in pg.inner_text('body')); ok_dialog(pg)
    ok &= check('BR-02 the list shows the company name and accent colour', 'Acme Co' in row().inner_text() and 'rgb(17, 34, 51)' in row().locator('span[title="Accent colour"]').evaluate('e => getComputedStyle(e).backgroundColor'))
    row().locator('[data-act="details"]').click(); pg.wait_for_timeout(500)
    ok &= check('BR-02 reopening shows what was saved', pg.input_value('#bd-gst') == '29ABCDE1234F1Z5' and pg.input_value('#bd-docfmt') == '2' and pg.input_value('#bd-wm-text') == 'COPY' and pg.input_value('#bd-wm-size') == 'large' and pg.input_value('#bd-bank-ifsc') == 'HDFC0001' and pg.is_visible('#bd-logo-preview'))
    pg.click('#bd-logo-remove'); ok &= check('BR-02 removing a logo hides its preview', not pg.is_visible('#bd-logo-preview')); pg.click('#branchDetailSaveBtn'); pg.wait_for_timeout(1800); ok_dialog(pg)
    row().locator('[data-act="numbering"]').click(); pg.wait_for_timeout(700)
    ok &= check('BR-02 numbering dialog lists the four document types', pg.inner_text('#branchNumberingTitle') == 'Document Numbering — Test Branch 2' and pg.locator('#branchNumberingBody > div').count() == 4)
    pg.fill('#bn-quotation-prefix', 'QX'); pg.fill('#bn-quotation-suffix', '/26'); pg.fill('#bn-quotation-start', '50'); pg.click('#branchNumberingSaveBtn'); pg.wait_for_timeout(1500)
    ok &= check('BR-02 numbering saved: confirmation', 'Numbering settings saved' in pg.inner_text('body')); ok_dialog(pg)
    row().locator('[data-act="numbering"]').click(); pg.wait_for_timeout(700)
    ok &= check('BR-02 numbering reloads with the next number', pg.input_value('#bn-quotation-prefix') == 'QX' and pg.input_value('#bn-quotation-start') == '50' and 'QX' in pg.inner_text('#branchNumberingBody'), pg.inner_text('#branchNumberingBody')[:200]); pg.click('#branchNumberingCancelBtn')
    row().locator('[data-act="remove"]').click(); pg.wait_for_timeout(400); ok_dialog(pg); pg.wait_for_timeout(1200)
    ok &= check('BR-01 remove a branch', 'Test Branch 2' not in pg.inner_text('#branchesList'))
    return ok

def run(p, parts=('manage',)):
    ok = True; b = launch(p)
    ctx, pg = login(b, 'admin', geo=False)
    errs = []; pg.on('pageerror', lambda e: errs.append(str(e)))
    if 'manage' in parts: ok &= manage(pg)
    if 'import' in parts: ok &= importing(pg)
    if 'backup' in parts: ok &= backup(pg)
    if 'users' in parts: ok &= users(pg)
    if 'branches' in parts: ok &= branches(pg)
    ok &= check('no page errors', not errs, '; '.join(errs[:3]))
    ctx.close(); b.close()
    print('ADMIN PASS' if ok else 'ADMIN FAILED')

if __name__ == '__main__':
    import sys
    with sync_playwright() as p: run(p, tuple(sys.argv[1:]) or ('manage',))
